const updateRSSSubscription = `-- name: UpdateRSSSubscription :one
WITH valid_input AS (
    SELECT 1
    WHERE NOT EXISTS (
        SELECT 1
        FROM unnest($3::text[]) AS requested(category_id)
        LEFT JOIN catalog.categories AS category
          ON category.id = requested.category_id
         AND category.enabled = true
        WHERE category.id IS NULL
    )
)
UPDATE rss.subscriptions AS subscription
SET
    name = $1::text,
    enabled = $2::boolean,
    category_ids = $3::text[],
    promotion_filters = $4::text[],
    price_filter = $5::text,
    bookmarked_only = $6::boolean,
    item_limit = $7::integer,
    include_category = $8::boolean,
    include_subtitle = $9::boolean,
    include_size = $10::boolean,
    include_promotion = $11::boolean,
    version = subscription.version + 1,
    updated_at = $12::timestamptz
FROM valid_input
WHERE subscription.id = $13::uuid
  AND subscription.user_id = $14::uuid
  AND subscription.version = $15::bigint
  AND subscription.revoked_at IS NULL
RETURNING
    subscription.id,
    subscription.name,
    subscription.enabled,
    subscription.token_version,
    subscription.category_ids,
    subscription.promotion_filters,
    subscription.price_filter,
    subscription.bookmarked_only,
    subscription.item_limit,
    subscription.include_category,
    subscription.include_subtitle,
    subscription.include_size,
    subscription.include_promotion,
    subscription.version,
    subscription.created_at,
    subscription.updated_at
`

