const upsertRSSFeedCache = `-- name: UpsertRSSFeedCache :exec
INSERT INTO rss.feed_cache (
    subscription_id,
    subscription_version,
    content_revision,
    observed_at,
    expires_at,
    next_boundary_at,
    item_projection,
    updated_at
) VALUES (
    $1::uuid,
    $2::bigint,
    $3::bigint,
    $4::timestamptz,
    $5::timestamptz,
    $6::timestamptz,
    $7::jsonb,
    $8::timestamptz
)
ON CONFLICT (subscription_id) DO UPDATE
SET
    subscription_version = EXCLUDED.subscription_version,
    content_revision = EXCLUDED.content_revision,
    observed_at = EXCLUDED.observed_at,
    expires_at = EXCLUDED.expires_at,
    next_boundary_at = EXCLUDED.next_boundary_at,
    item_projection = EXCLUDED.item_projection,
    updated_at = EXCLUDED.updated_at
`

